package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SectorIdentifierUriVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property sector identifier uri of trusted client ")
  void test_sector_identifier_uri_v_o_builder() {
    Assertions.assertFalse(SectorIdentifierUriVO.nullValue().getSectorIdentifierUri().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(SectorIdentifierUriVO.tryFrom(null).getSectorIdentifierUri().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        SectorIdentifierUriVO.from("one").getSectorIdentifierUri().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> SectorIdentifierUriVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", SectorIdentifierUriVO.from("one").toString());
  }
}
